CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations(id uuid PRIMARY KEY,slug text NOT NULL UNIQUE,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,disabled_at timestamptz);
CREATE TABLE projects(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),slug text NOT NULL,name text NOT NULL,UNIQUE(organization_id,slug),UNIQUE(id,organization_id));
CREATE TABLE memberships(organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('owner','admin','analyst','viewer')),project_id uuid,PRIMARY KEY(organization_id,user_id),FOREIGN KEY(project_id,organization_id) REFERENCES projects(id,organization_id),CHECK((role='admin' AND project_id IS NOT NULL) OR (role<>'admin' AND project_id IS NULL)));
CREATE TABLE environments(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),slug text NOT NULL,name text NOT NULL,UNIQUE(project_id,slug));
CREATE TABLE servers(id uuid PRIMARY KEY,environment_id uuid NOT NULL REFERENCES environments(id),display_name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agents(id uuid PRIMARY KEY,server_id uuid NOT NULL REFERENCES servers(id),installation_id uuid NOT NULL UNIQUE,last_seen_at timestamptz,last_observed_at timestamptz,agent_version text NOT NULL DEFAULT '',queue_depth integer NOT NULL DEFAULT 0,clock_skew_warning boolean NOT NULL DEFAULT false,revoked_at timestamptz);
CREATE TABLE agent_tokens(id uuid PRIMARY KEY,agent_id uuid NOT NULL REFERENCES agents(id),prefix text NOT NULL,secret_hash text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days',revoked_at timestamptz);
CREATE TABLE user_sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE change_events(id uuid PRIMARY KEY,agent_id uuid NOT NULL REFERENCES agents(id),sequence bigint NOT NULL CHECK(sequence>0),event_uuid uuid NOT NULL,file_alias text NOT NULL,kind text NOT NULL CHECK(kind IN('baseline','missing_initial','created','modified','deleted','unreadable','restored','recovered','metadata_changed','unstable')),old_sha256 text NOT NULL DEFAULT '',new_sha256 text NOT NULL DEFAULT '',file_size bigint NOT NULL DEFAULT 0,mode bigint NOT NULL DEFAULT 0,mtime timestamptz,observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),payload_hash text NOT NULL,severity text NOT NULL,UNIQUE(agent_id,sequence),UNIQUE(agent_id,event_uuid));
CREATE INDEX events_received ON change_events(received_at DESC,id DESC);
CREATE INDEX events_agent_received ON change_events(agent_id,received_at DESC,id DESC);
CREATE TABLE file_observations(agent_id uuid NOT NULL REFERENCES agents(id),file_alias text NOT NULL,sha256 text NOT NULL,state text NOT NULL,file_size bigint NOT NULL,mode bigint NOT NULL,mtime timestamptz,observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),sequence bigint NOT NULL,PRIMARY KEY(agent_id,file_alias));
CREATE TABLE acknowledgements(id uuid PRIMARY KEY,event_id uuid NOT NULL REFERENCES change_events(id) ON DELETE CASCADE,actor_id uuid NOT NULL REFERENCES users(id),comment text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid REFERENCES users(id),operation text NOT NULL,target_type text NOT NULL,target_id uuid NOT NULL,data_redacted jsonb NOT NULL DEFAULT '{}',timestamp timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org ON audit_logs(organization_id,timestamp DESC,id DESC);
INSERT INTO schema_migrations(version) VALUES(1);
